def maxsubarray(x):
	max_sum = max(x)
	max_tillnow = 0
	for i in range(0, len(x)):
		max_tillnow += x[i]
		if max_tillnow > max_sum:
			max_sum = max_tillnow
		if max_tillnow < 0:
			max_tillnow = 0
	return max_sum
